-- =========================================================
-- supabase/seed/website-content-drafts.sql
-- =========================================================
-- Textos de venta iniciales del sitio (EN/ES) escritos por Claude para
-- que Alejo los revise y corrija dentro de Marine Cloud.
--
-- * Todo entra como BORRADOR (published = false): nada aparece en el
--   sitio hasta que Alejo pulse "Publicar" en KCC Admin → Website.
-- * Idempotente: se puede correr varias veces. No pisa nada que ya
--   exista (on conflict do nothing) ni textos de Ajustes ya editados.
-- * NO incluye proyectos ni testimonios: esos tienen que ser reales,
--   con fotos y permiso del cliente. Tampoco inventa ofertas, precios
--   ni cifras (años, cantidad de trabajos).
-- * Requiere la migración 20261001000000_website_studio.sql.
-- =========================================================

insert into site_services (slug, category, icon, featured, sort_order, published, title, summary, body, benefits, seo_title, seo_description)
values ($txt$marine-electrical$txt$, $txt$electrical$txt$, $txt$bolt$txt$, true, 10, false,
  $json${"en": "Marine Electrical Systems", "es": "Sistemas eléctricos marinos"}$json$::jsonb, $json${"en": "Wiring, panels and electrical upgrades done to marine standards — so your systems work every time you turn the key.", "es": "Cableado, paneles y mejoras eléctricas hechas con estándares marinos, para que tus sistemas funcionen cada vez que giras la llave."}$json$::jsonb, $json${"en": "Most electrical problems on a boat start small: a corroded connection, an undersized wire, a breaker that trips for no clear reason. Left alone, they turn into a dead battery at the dock or a system that fails offshore.\n\nWe rework wiring, upgrade and label panels, replace damaged circuits and install new equipment with marine-rated materials, correct wire sizing and protected connections. Before any work starts you get a clear estimate to approve, and when we finish you get before-and-after photos and a written record of what was done.", "es": "La mayoría de los problemas eléctricos en una embarcación empiezan pequeños: una conexión sulfatada, un cable delgado, un breaker que salta sin razón clara. Si se dejan, terminan en una batería muerta en el muelle o un sistema que falla mar adentro.\n\nRehacemos cableado, actualizamos y rotulamos paneles, reemplazamos circuitos dañados e instalamos equipos nuevos con materiales de grado marino, el calibre correcto y conexiones protegidas. Antes de empezar recibes un presupuesto claro para aprobar, y al terminar recibes fotos de antes y después y un registro escrito de lo que se hizo."}$json$::jsonb, $json$[{"en": "Fewer surprises on the water", "es": "Menos sorpresas en el agua"}, {"en": "Clean, labeled panels anyone can understand", "es": "Paneles limpios y rotulados que cualquiera entiende"}, {"en": "Marine-rated materials, not hardware-store parts", "es": "Materiales de grado marino, no repuestos de ferretería"}, {"en": "Photos and a written record of every change", "es": "Fotos y registro escrito de cada cambio"}]$json$::jsonb, $json${"en": "Marine Electrical Repair & Rewiring", "es": "Reparación eléctrica marina y recableado"}$json$::jsonb, $json${"en": "Boat wiring, panel upgrades and electrical repairs to marine standards, documented with photos. Request service in two minutes.", "es": "Cableado, paneles y reparaciones eléctricas de embarcaciones con estándares marinos, documentado con fotos. Solicita servicio en dos minutos."}$json$::jsonb)
on conflict (slug) do nothing;

insert into site_services (slug, category, icon, featured, sort_order, published, title, summary, body, benefits, seo_title, seo_description)
values ($txt$diagnostics$txt$, $txt$electrical$txt$, $txt$pulse$txt$, true, 20, false,
  $json${"en": "Electrical Troubleshooting & Diagnostics", "es": "Diagnóstico y solución de fallas eléctricas"}$json$::jsonb, $json${"en": "Something stopped working and nobody can tell you why? We trace the fault to its root cause before replacing anything.", "es": "¿Algo dejó de funcionar y nadie te dice por qué? Rastreamos la falla hasta su causa real antes de cambiar cualquier pieza."}$json$::jsonb, $json${"en": "Intermittent electrical faults are the most frustrating problem a boat owner can have — and the most expensive when someone guesses and starts replacing parts.\n\nWe test methodically: voltage drop, grounding, continuity, loads and connections, system by system, until the actual cause is found. You get a written diagnosis with what we found and what it will take to fix it, so you decide with real information.", "es": "Las fallas eléctricas intermitentes son el problema más frustrante para un dueño de embarcación, y el más caro cuando alguien adivina y empieza a cambiar piezas.\n\nProbamos con método: caída de voltaje, tierras, continuidad, cargas y conexiones, sistema por sistema, hasta encontrar la causa real. Recibes un diagnóstico escrito con lo que encontramos y lo que hace falta para repararlo, para que decidas con información real."}$json$::jsonb, $json$[{"en": "Root cause found before money is spent on parts", "es": "Se encuentra la causa antes de gastar en repuestos"}, {"en": "A written diagnosis you can keep", "es": "Un diagnóstico escrito que puedes conservar"}, {"en": "You approve the repair price first", "es": "Tú apruebas primero el precio de la reparación"}]$json$::jsonb, $json${"en": "Boat Electrical Diagnostics & Troubleshooting", "es": "Diagnóstico eléctrico de embarcaciones"}$json$::jsonb, $json${"en": "Intermittent electrical problems traced to the root cause, with a written diagnosis before any repair.", "es": "Fallas eléctricas intermitentes rastreadas hasta la causa real, con diagnóstico escrito antes de cualquier reparación."}$json$::jsonb)
on conflict (slug) do nothing;

insert into site_services (slug, category, icon, featured, sort_order, published, title, summary, body, benefits, seo_title, seo_description)
values ($txt$batteries-charging$txt$, $txt$electrical$txt$, $txt$battery$txt$, true, 30, false,
  $json${"en": "Batteries, Charging & Shore Power", "es": "Baterías, carga y conexión a muelle"}$json$::jsonb, $json${"en": "Batteries that die overnight, chargers that never finish, shore power that trips — we size and fix the whole charging system.", "es": "Baterías que amanecen descargadas, cargadores que nunca terminan, conexión a muelle que se dispara: dimensionamos y reparamos todo el sistema de carga."}$json$::jsonb, $json${"en": "A battery problem is rarely just the battery. We check the bank, the charger, the alternator output, isolators, parasitic draws and shore-power connections together, then recommend only what the system actually needs.\n\nIf you are upgrading — more capacity, lithium, a new inverter or charger — we design it so every part works together safely.", "es": "Un problema de batería casi nunca es solo la batería. Revisamos juntos el banco, el cargador, la salida del alternador, aisladores, consumos parásitos y la conexión a muelle, y recomendamos solo lo que el sistema realmente necesita.\n\nSi vas a mejorar — más capacidad, litio, un inversor o cargador nuevo — lo diseñamos para que cada parte funcione en conjunto de forma segura."}$json$::jsonb, $json$[{"en": "Batteries that are charged when you arrive", "es": "Baterías cargadas cuando llegas"}, {"en": "Only the parts the system really needs", "es": "Solo las piezas que el sistema realmente necesita"}, {"en": "Safe installation of chargers and inverters", "es": "Instalación segura de cargadores e inversores"}]$json$::jsonb, $json${"en": "Boat Battery, Charger & Shore Power Service", "es": "Servicio de baterías, cargadores y conexión a muelle"}$json$::jsonb, $json${"en": "Battery banks, chargers, inverters and shore power diagnosed and installed as one system.", "es": "Bancos de baterías, cargadores, inversores y conexión a muelle diagnosticados e instalados como un solo sistema."}$json$::jsonb)
on conflict (slug) do nothing;

insert into site_services (slug, category, icon, featured, sort_order, published, title, summary, body, benefits, seo_title, seo_description)
values ($txt$preventive-maintenance$txt$, $txt$maintenance$txt$, $txt$wrench$txt$, true, 40, false,
  $json${"en": "Preventive Maintenance & Systems Check", "es": "Mantenimiento preventivo y revisión de sistemas"}$json$::jsonb, $json${"en": "A scheduled check of your boat's electrical and onboard systems, so problems are caught at the dock — not on the water.", "es": "Una revisión programada de los sistemas eléctricos y de a bordo, para detectar problemas en el muelle y no en el agua."}$json$::jsonb, $json${"en": "Preventive maintenance is the cheapest repair there is. On a scheduled visit we inspect and test batteries and charging, wiring and connections, pumps and float switches, lights, electronics power and the items that most often fail without warning.\n\nYou receive a report with photos of what we checked, what is in good condition and what needs attention — ranked by priority, with prices, so you can plan instead of react.", "es": "El mantenimiento preventivo es la reparación más barata que existe. En una visita programada inspeccionamos y probamos baterías y carga, cableado y conexiones, bombas y flotadores, luces, alimentación de equipos electrónicos y lo que más suele fallar sin aviso.\n\nRecibes un reporte con fotos de lo revisado, lo que está en buen estado y lo que necesita atención — ordenado por prioridad y con precios — para que planifiques en vez de reaccionar."}$json$::jsonb, $json$[{"en": "Problems caught before they leave you stranded", "es": "Problemas detectados antes de que te dejen varado"}, {"en": "A photo report of your boat's condition", "es": "Un reporte con fotos del estado de tu embarcación"}, {"en": "Repairs ranked by priority, with prices", "es": "Reparaciones ordenadas por prioridad, con precios"}, {"en": "A service history that adds value when you sell", "es": "Un historial de servicio que suma valor al vender"}]$json$::jsonb, $json${"en": "Boat Preventive Maintenance & Systems Inspection", "es": "Mantenimiento preventivo e inspección de embarcaciones"}$json$::jsonb, $json${"en": "Scheduled inspection of batteries, wiring, pumps and onboard systems with a photo report and prioritized recommendations.", "es": "Inspección programada de baterías, cableado, bombas y sistemas de a bordo con reporte fotográfico y recomendaciones priorizadas."}$json$::jsonb)
on conflict (slug) do nothing;

insert into site_services (slug, category, icon, featured, sort_order, published, title, summary, body, benefits, seo_title, seo_description)
values ($txt$pumps-bilge$txt$, $txt$maintenance$txt$, $txt$pump$txt$, false, 50, false,
  $json${"en": "Bilge Pumps & Water Systems", "es": "Bombas de achique y sistemas de agua"}$json$::jsonb, $json${"en": "Bilge pumps, float switches and freshwater systems tested and repaired — the systems that protect your boat when you are not there.", "es": "Bombas de achique, flotadores y sistemas de agua dulce probados y reparados: los sistemas que protegen tu embarcación cuando no estás."}$json$::jsonb, $json${"en": "A bilge pump that does not start when it should can sink a boat at the dock. We test pumps, float switches, wiring and alarms under real conditions, replace what is failing and leave the system working automatically.\n\nWe also service freshwater pumps, pressure systems and the wiring behind them.", "es": "Una bomba de achique que no arranca cuando debe puede hundir una embarcación en el muelle. Probamos bombas, flotadores, cableado y alarmas en condiciones reales, reemplazamos lo que falla y dejamos el sistema funcionando en automático.\n\nTambién damos servicio a bombas de agua dulce, sistemas de presión y su cableado."}$json$::jsonb, $json$[{"en": "Automatic protection that actually works", "es": "Protección automática que realmente funciona"}, {"en": "Tested under real conditions", "es": "Probado en condiciones reales"}]$json$::jsonb, $json${"en": "Bilge Pump Repair & Water Systems", "es": "Reparación de bombas de achique y sistemas de agua"}$json$::jsonb, $json${"en": "Bilge pumps, float switches, alarms and freshwater systems tested and repaired.", "es": "Bombas de achique, flotadores, alarmas y sistemas de agua dulce probados y reparados."}$json$::jsonb)
on conflict (slug) do nothing;

insert into site_landing_pages (path, internal_name, service_id, headline, subheadline, bullets, cta_label, utm_source, utm_campaign, published)
values ($txt$offers/marine-electrical$txt$, $txt$Facebook — Electrical (Oct 2026)$txt$, (select id from site_services where slug = $txt$marine-electrical$txt$),
  $json${"en": "Electrical problem on your boat? We find the cause and fix it right.", "es": "¿Falla eléctrica en tu embarcación? Encontramos la causa y la reparamos bien."}$json$::jsonb, $json${"en": "Batteries that die, breakers that trip, equipment that turns off on its own. A marine technician diagnoses the real cause, you approve the price, and you get photos of every repair.", "es": "Baterías que se descargan, breakers que saltan, equipos que se apagan solos. Un técnico marino diagnostica la causa real, tú apruebas el precio y recibes fotos de cada reparación."}$json$::jsonb, $json$[{"en": "Diagnosis of the real cause — not guesswork", "es": "Diagnóstico de la causa real, no adivinanzas"}, {"en": "You approve the price before any work starts", "es": "Apruebas el precio antes de empezar"}, {"en": "Marine-rated parts and correct wiring", "es": "Repuestos de grado marino y cableado correcto"}, {"en": "Before-and-after photos and a written report", "es": "Fotos de antes y después y reporte escrito"}, {"en": "Follow the job live from your phone", "es": "Sigue el trabajo en vivo desde tu celular"}]$json$::jsonb, $json${"en": "Get my diagnosis", "es": "Quiero mi diagnóstico"}$json$::jsonb, $txt$facebook$txt$, $txt$electrical-oct-2026$txt$, false)
on conflict (path) do nothing;

insert into site_landing_pages (path, internal_name, service_id, headline, subheadline, bullets, cta_label, utm_source, utm_campaign, published)
values ($txt$offers/boat-maintenance$txt$, $txt$Facebook — Maintenance (Oct 2026)$txt$, (select id from site_services where slug = $txt$preventive-maintenance$txt$),
  $json${"en": "Keep your boat ready to go.", "es": "Tu embarcación, lista para salir."}$json$::jsonb, $json${"en": "Preventive maintenance with a photo report. We inspect and test the systems that fail without warning — batteries, wiring, pumps, lights — and give you a prioritized list with prices. No surprises on the water.", "es": "Mantenimiento preventivo con reporte fotográfico. Revisamos y probamos los sistemas que fallan sin aviso — baterías, cableado, bombas, luces — y te entregamos una lista priorizada con precios. Sin sorpresas en el agua."}$json$::jsonb, $json$[{"en": "Problems caught at the dock, not offshore", "es": "Problemas detectados en el muelle, no mar adentro"}, {"en": "Photo report of your boat's condition", "es": "Reporte con fotos del estado de tu embarcación"}, {"en": "Repairs ranked by priority, with prices", "es": "Reparaciones por prioridad, con precios"}, {"en": "A service history that adds value when you sell", "es": "Historial de servicio que suma valor al vender"}]$json$::jsonb, $json${"en": "Schedule my inspection", "es": "Agendar mi revisión"}$json$::jsonb, $txt$facebook$txt$, $txt$maintenance-oct-2026$txt$, false)
on conflict (path) do nothing;

update site_settings set tagline = $json${"en": "Marine electrical & maintenance", "es": "Electricidad y mantenimiento marino"}$json$::jsonb where id = true and tagline = '{}'::jsonb;

update site_settings set hero_headline = $json${"en": "Your boat, working right. Every time you leave the dock.", "es": "Tu embarcación funcionando bien, cada vez que sales del muelle."}$json$::jsonb where id = true and hero_headline = '{}'::jsonb;

update site_settings set hero_subheadline = $json${"en": "Professional marine electrical work, diagnostics and maintenance — documented with photos and a written report on every job, so you know exactly what was done.", "es": "Trabajo eléctrico marino, diagnóstico y mantenimiento de nivel profesional — documentado con fotos y un reporte escrito en cada trabajo, para que sepas exactamente qué se hizo."}$json$::jsonb where id = true and hero_subheadline = '{}'::jsonb;

update site_settings set primary_cta_label = $json${"en": "Request service", "es": "Solicitar servicio"}$json$::jsonb where id = true and primary_cta_label = '{}'::jsonb;

select (select count(*) from site_services) as services, (select count(*) from site_landing_pages) as landing_pages;
